<?php
$labels=['CREATE'=>'Dibuat','APPROVE'=>'Disetujui Admin','REJECT'=>'Ditolak Admin','HANDOVER'=>'Diserahkan ke Teknisi','RETURN_REQUEST'=>'Pengembalian Diajukan','RETURN_PROCESSED'=>'Pengembalian Diproses','UPDATE'=>'Diperbarui','DELETE'=>'Dihapus'];
$icons=['CREATE'=>'fa-plus','APPROVE'=>'fa-check','REJECT'=>'fa-times','HANDOVER'=>'fa-hand-holding','RETURN_REQUEST'=>'fa-undo','RETURN_PROCESSED'=>'fa-box-open','UPDATE'=>'fa-edit','DELETE'=>'fa-trash'];
$colors=['CREATE'=>'green','APPROVE'=>'indigo','REJECT'=>'red','HANDOVER'=>'blue','RETURN_REQUEST'=>'orange','RETURN_PROCESSED'=>'green','UPDATE'=>'blue','DELETE'=>'red'];
?>
<div class="bg-white dark:bg-gray-800 shadow rounded-lg p-6 mt-6 border-t-4 border-blue-500"><h3 class="text-lg font-bold text-gray-800 dark:text-gray-100 mb-4"><i class="fas fa-history mr-2 text-blue-500"></i> Riwayat Status & Aktivitas</h3>
